import java.io.BufferedInputStream

private class Input {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var position = 0

    private fun readByte(): Int {
        if (position >= length) {
            length = input.read(buffer)
            position = 0
            if (length <= 0) return -1
        }
        return buffer[position++].toInt()
    }

    fun nextOrNull(): String? {
        val result = StringBuilder()
        var c: Int

        do {
            c = readByte()
            if (c == -1) return null
        } while (c <= 32)

        while (c > 32 && c != -1) {
            result.append(c.toChar())
            c = readByte()
        }
        return result.toString()
    }

    fun next(): String = nextOrNull() ?: ""
}

private val globalInput = Input()

private fun cube(x: Int): Long {
    return x.toLong() * x.toLong() * x.toLong()
}

private fun foo(n: Long): Long {
    var ans = 0L
    var k = 2
    while (true) {
        val x = n / cube(k)
        if (x == 0L) break
        ans += x
        k++
    }
    return ans
}

private fun binSearch(
    f: (Long) -> Boolean,
    initialLo: Long,
    initialUp: Long,
    eps: Long
): Long {
    var lo = initialLo
    val up = initialUp + 1L
    var cnt = up - lo

    while (cnt >= eps) {
        val step = cnt / 2L
        val mid = lo + step
        if (!f(mid)) {
            lo = mid + eps
            cnt -= step + eps
        } else {
            cnt = step
        }
    }
    return lo
}

