private typealias FLess = (Int, Int) -> Boolean
private typealias FSwap = (Int, Int) -> Unit

private fun wsort(length: Int, less: FLess, swap: FSwap) {
    fun siftDown(start: Int, end: Int) {
        var root = start
        while (root * 2 + 1 <= end) {
            var child = root * 2 + 1
            if (child + 1 <= end && less(child, child + 1)) {
                child++
            }
            if (!less(root, child)) {
                return
            }
            swap(root, child)
            root = child
        }
    }

    var start = length / 2 - 1
    while (start >= 0) {
        siftDown(start, length - 1)
        start--
    }

    var end = length - 1
    while (end > 0) {
        swap(0, end)
        end--
        siftDown(0, end)
    }
}

